from taf.cloud.cbam.interfaces.cbam18 import CBAM18
from taf.cloud.cbam.interfaces.cbam19 import CBAM19
from taf.cloud.cbam.interfaces.cbam19_5 import CBAM19_5


class SupportedCbams(object):
    cbam18_0 = CBAM18
    cbam18_5 = CBAM18
    cbam19_0 = CBAM19
    cbam19_5 = CBAM19_5


class CbamVersionNotSupported(Exception):
    pass


class CbamProvider(object):
    @classmethod
    def create_cbam(cls, version, ip, client_id, client_secret,
                    verify=False, vnfm_api_version=None):

        cbam_type = getattr(SupportedCbams, version, None)

        if not cbam_type:
            exc_msg = "Version {} of CBAM is not supported."
            exc_msg = exc_msg.format(version)
            raise CbamVersionNotSupported(exc_msg)

        cbam = cbam_type(
            ip=ip, client_id=client_id, client_secret=client_secret, verify=verify, vnfm_api_version=vnfm_api_version)
        return cbam
